from bioblend.galaxy import GalaxyInstance
import json

gi = GalaxyInstance('https://usegalaxy.org', key='51f5558e4783cd02b99a7ad00e0eab59')
hist_id = 'bbd44e69cb8906b523907423ea721747'
tool_id = 'toolshed.g2.bx.psu.edu/repos/goeckslab/phykit_metrics/phykit_metrics/0.2.0+galaxy0'

# First, let's check the actual Galaxy API format needed by looking at what BioBlend sends
# Try with selector_values as a top-level parameter (Galaxy 23.0+ style)
inputs = {
    'operation': {
        'input_mode': {
            'archive': {'src': 'hda', 'id': 'f9cad7b01a47213500bb2130b9595d03'},
            'filter_suffix': '.treefile',
        }
    }
}

# Check if selector_values can be passed via the tool_inputs
# Actually, let me try using the create_tool_execution API directly with selector_values
import requests

api_key = '51f5558e4783cd02b99a7ad00e0eab59'
base_url = 'https://usegalaxy.org'

# The Galaxy API for tool execution with selector_values
url = f'{base_url}/api/tools/{tool_id}/builds/latest'
headers = {'x-api-key': api_key}

# Get the tool model to understand what params it needs
resp = requests.get(url, headers=headers)
tool_model = resp.json()
print(f"Tool model version: {tool_model.get('version')}")

# Now let's try the execution with selector_values
url_exec = f'{base_url}/api/tools'
payload = {
    'history_id': hist_id,
    'tool_id': tool_id,
    'input_format': '21.01',
    'inputs': json.dumps({
        'operation': {
            'input_mode': {
                'archive': {'src': 'hda', 'id': 'f9cad7b01a47213500bb2130b9595d03'},
                'filter_suffix': '.treefile',
            }
        }
    }),
    'selector_values': json.dumps({
        'operation|selector': 'treeness',
        'operation|input_mode|selector': 'zip_archive',
    })
}

print(f"\nTrying with selector_values...")
print(f"Payload: {json.dumps({k: v for k, v in payload.items() if k != 'inputs'}, indent=2)}")

resp = requests.post(url_exec, headers=headers, data=payload)
print(f"Status: {resp.status_code}")
result = resp.json()
print(json.dumps({k: str(v)[:200] for k, v in result.items()}, indent=2))
if 'outputs' in result:
    print(f"Outputs: {result['outputs']}")
if 'jobs' in result:
    print(f"Jobs: {result['jobs']}")
